namespace {
core::TorrentHash ratingHash(const std::string& bytes){auto value=core::TorrentHash::parse(bytes);need(bool(value),"Generated rating hash");return *value;}
std::string ratingKey(const std::string& hash){auto application=plugins::rating::lookupKey(std::span(reinterpret_cast<const std::uint8_t*>(hash.data()),hash.size()));need(bool(application),"Generated rating application key");const auto digest=QCryptographicHash::hash(QByteArray(reinterpret_cast<const char*>(application->data()),application->size()),QCryptographicHash::Sha1);return digest.toStdString();}
void localRating(Client& client,const std::string& hash,int score){auto store=storage::TorrentStateStore::open(*client.lease);need(bool(store),"Generated rating store");auto state=store->loadAttributes(*client.lease,ratingHash(hash));need(bool(state),"Generated rating state");const auto* a=state->document().find("attributes");need(a!=nullptr,"Generated attributes");auto encoded=core::encodeValue(*a);need(bool(encoded),"Generated attribute encoding");auto attributes=core::Document::parse(*encoded);need(bool(attributes),"Generated attribute document");need(attributes->replaceValue("Plugin.azrating.rating","1:"+std::to_string(score)).has_value(),"Generated local score");need(attributes->replaceValue("Plugin.azrating.comment","7:Fixture").has_value(),"Generated local comment");need(store->saveAttributes(*client.lease,*state,attributes->serialize()).has_value(),"Generated local rating saved");}
std::shared_ptr<const app::SharedRatingSnapshot> ratingView(Client& client,const std::string& hash,bool byHash=false){auto snapshot=client.service->snapshot();if(snapshot){for(const auto& row:snapshot->ratings){if(row->hash==ratingHash(hash).hex()&&row->byHash==byHash){return row;}}}return {};}
void noRcm(Client& client){auto config=storage::ConfigFile::load(*client.lease,"biglybt.config");need(bool(config)&&config->document().replaceValue("rcm.overall.enabled","i0e").has_value()&&config->save(*client.lease).has_value(),"Generated RCM disable");}
}
